+static LAST_CALLBACK_BASE_FRAMES: AtomicU64 = AtomicU64::new(0);
+static LAST_CALLBACK_FRAMES: AtomicU64 = AtomicU64::new(0);
+static PREV_CALLBACK_ELAPSED_NANOS: AtomicU64 = AtomicU64::new(0);
