+    LAST_CALLBACK_BASE_FRAMES.store(total_before, Ordering::Relaxed);
+    LAST_CALLBACK_FRAMES.store(0, Ordering::Relaxed);
+    LAST_CALLBACK_ELAPSED_NANOS.store(anchor_nanos.saturating_add(1), Ordering::Relaxed);
+    end_callback_clock_write();
+}
+
+#[inline(always)]
+pub fn publish_callback_window_end(total_before: u64, frames: u64) {
+    begin_callback_clock_write();
+    LAST_CALLBACK_FRAMES.store(frames, Ordering::Relaxed);
+    MUSIC_TOTAL_FRAMES.store(total_before.saturating_add(frames), Ordering::Relaxed);
+    end_callback_clock_write();
+}
+
+pub fn load_callback_clock_snapshot_now<F>(
+    mut clock_nanos: F,
+) -> (Instant, u64, CallbackClockSource, CallbackClockWindow)
+where
+    F: FnMut(Instant, CallbackClockSource) -> Option<u64>,
+{
+    loop {
+        let seq_start = CALLBACK_CLOCK_SEQ.load(Ordering::Acquire);
+        if seq_start & 1 != 0 {
+            std::hint::spin_loop();
+            continue;
+        }
+        let source = CallbackClockSource::load();
+        let valid_at = Instant::now();
+        let at_nanos = clock_nanos(valid_at, source);
+        let window = CallbackClockWindow {
+            total_frames: MUSIC_TOTAL_FRAMES.load(Ordering::Relaxed),
+            last_nanos: LAST_CALLBACK_ELAPSED_NANOS.load(Ordering::Relaxed),
+            last_base_frames: LAST_CALLBACK_BASE_FRAMES.load(Ordering::Relaxed),
+            last_callback_frames: LAST_CALLBACK_FRAMES.load(Ordering::Relaxed),
+            prev_nanos: PREV_CALLBACK_ELAPSED_NANOS.load(Ordering::Relaxed),
+            prev_base_frames: PREV_CALLBACK_BASE_FRAMES.load(Ordering::Relaxed),
+            prev_callback_frames: PREV_CALLBACK_FRAMES.load(Ordering::Relaxed),
+        };
+        let seq_end = CALLBACK_CLOCK_SEQ.load(Ordering::Acquire);
+        if seq_start == seq_end {
+            let at_nanos = at_nanos.unwrap_or_else(|| window.last_nanos.saturating_sub(1));
+            return (valid_at, at_nanos, source, window);
+        }
+    }
+}
+
+#[inline(always)]
+fn stream_position_frames_from_callback(
+    sample_rate: u32,
+    start_frame: u64,
+    at_nanos: u64,
+    cb_nanos_plus_one: u64,
+    base_frames: u64,
+    buf_frames: u64,
+) -> Option<f64> {
+    if cb_nanos_plus_one == 0 {
+        return None;
+    }
+    let cb_nanos = cb_nanos_plus_one - 1;
+    if at_nanos < cb_nanos {
+        return None;
+    }
+    let dt = ((at_nanos - cb_nanos) as f64) * 1e-9;
+    // Guarded unsigned differences and integer rates produce finite, nonnegative frames.
+    let frames_since_cb = (dt * f64::from(sample_rate)).min(buf_frames as f64);
+    let frames_now = base_frames as f64 + frames_since_cb;
+    Some(frames_now.max(start_frame as f64) - start_frame as f64)
+}
+
+#[inline(always)]
+fn stream_position_frames_from_anchor_pair(
+    start_frame: u64,
+    at_nanos: u64,
+    earlier_nanos_plus_one: u64,
+    earlier_base_frames: u64,
+    later_nanos_plus_one: u64,
+    later_base_frames: u64,
+) -> Option<f64> {
+    if earlier_nanos_plus_one == 0 || later_nanos_plus_one == 0 {
+        return None;
+    }
+    let earlier_nanos = earlier_nanos_plus_one - 1;
+    let later_nanos = later_nanos_plus_one - 1;
+    if later_nanos <= earlier_nanos || later_base_frames <= earlier_base_frames {
+        return None;
+    }
+    // Ordered u64 anchors guarantee positive, finite spans and slope.
+    let nanos_span = (later_nanos - earlier_nanos) as f64;
+    let frames_per_ns = (later_base_frames - earlier_base_frames) as f64 / nanos_span;
+    let dt_ns = at_nanos as f64 - later_nanos as f64;
+    let frames_now = later_base_frames as f64 + dt_ns * frames_per_ns;
+    Some(frames_now.max(start_frame as f64) - start_frame as f64)
+}
+
+#[inline(always)]
+#[must_use]
+pub fn stream_position_frames_from_window(
+    sample_rate: u32,
+    start_frame: u64,
+    at_nanos: u64,
+    window: CallbackClockWindow,
+) -> Option<f64> {
+    stream_position_frames_from_callback(
+        sample_rate,
+        start_frame,
+        at_nanos,
+        window.last_nanos,
+        window.last_base_frames,
+        window.last_callback_frames,
+    )
+    .or_else(|| {
+        stream_position_frames_from_callback(
+            sample_rate,
+            start_frame,
+            at_nanos,
+            window.prev_nanos,
+            window.prev_base_frames,
+            window.prev_callback_frames,
+        )
+    })
+    .or_else(|| {
+        stream_position_frames_from_anchor_pair(
+            start_frame,
+            at_nanos,
+            window.prev_nanos,
+            window.prev_base_frames,
+            window.last_nanos,
+            window.last_base_frames,
+        )
+    })
+}
+
+#[inline(always)]
+#[must_use]
+pub const fn fallback_stream_position_frames(start_frame: u64, window: CallbackClockWindow) -> f64 {
+    window.total_frames.saturating_sub(start_frame) as f64
+}
+
+pub struct PlaybackPosMap {
+    queue: VecDeque<MusicMapSeg>,
+    backlog_frames: i64,
+    ordered: bool,
+}
+
+impl Default for PlaybackPosMap {
+    fn default() -> Self {
+        Self { queue: VecDeque::new(), backlog_frames: 0, ordered: true }
+    }
+}
+
+impl PlaybackPosMap {
+    pub fn clear(&mut self) {
+        self.queue.clear();
+        self.backlog_frames = 0;
+        self.ordered = true;
+    }
+
+    pub fn insert(&mut self, seg: MusicMapSeg) {
+        if seg.frames <= 0
+            || !seg.music_start_sec.is_finite()
+            || !seg.music_sec_per_frame.is_finite()
+        {
+            return;
+        }
+        if let Some(last) = self.queue.back_mut() {
+            self.ordered &= last.stream_frame_start as f64 + last.frames as f64
+                <= seg.stream_frame_start as f64;
+            let contiguous_stream = last.stream_frame_start + last.frames == seg.stream_frame_start;
+            let ratio_match = (last.music_sec_per_frame - seg.music_sec_per_frame).abs() <= 1e-9;
+            if contiguous_stream && ratio_match && {
+                let expected_music_start = last
+                    .music_sec_per_frame
+                    .mul_add(last.frames as f64, last.music_start_sec);
+                (expected_music_start - seg.music_start_sec).abs()
+                    <= seg.music_sec_per_frame.abs().max(1e-9)
+            } {
+                last.frames += seg.frames;
+                self.backlog_frames = self.backlog_frames.saturating_add(seg.frames);
+                self.cleanup();
+                return;
+            }
+        }
+        self.backlog_frames = self.backlog_frames.saturating_add(seg.frames);
+        self.queue.push_back(seg);
+        self.cleanup();
+    }
+
+    fn cleanup(&mut self) {
+        while self.backlog_frames > MUSIC_POS_MAP_BACKLOG_FRAMES {
+            let Some(front) = self.queue.front_mut() else {
+                self.backlog_frames = 0;
+                break;
+            };
+            let excess = self.backlog_frames - MUSIC_POS_MAP_BACKLOG_FRAMES;
+            if excess >= front.frames {
+                // Fully expired segments need no timestamp adjustment.
+                self.backlog_frames -= front.frames;
+                self.queue.pop_front();
+                continue;
+            }
+            front.stream_frame_start += excess;
+            front.music_start_sec = front
+                .music_sec_per_frame
+                .mul_add(excess as f64, front.music_start_sec);
+            front.frames -= excess;
+            self.backlog_frames -= excess;
+            // Trimming can change the rounded floating endpoint at large
+            // stream positions, even though the integer endpoint is unchanged.
+            if self.ordered && self.queue.len() > 1 {
+                let front = &self.queue[0];
+                self.ordered = front.stream_frame_start as f64 + front.frames as f64
+                    <= self.queue[1].stream_frame_start as f64;
+            }
+        }
+    }
+
+    #[must_use]
+    pub fn search(&self, stream_frame: f64) -> Option<(f64, f64)> {
+        if !stream_frame.is_finite() {
+            return None;
+        }
+        if self.ordered && let Some(seg) = self.queue.back() {
+            let start = seg.stream_frame_start as f64;
+            if stream_frame >= start && stream_frame < start + seg.frames as f64 {
+                return Some(((stream_frame - start).mul_add(seg.music_sec_per_frame, seg.music_start_sec), seg.music_sec_per_frame));
+            }
+        }
+        let mut closest = None;
+        let mut closest_dist = f64::INFINITY;
+        for seg in &self.queue {
+            let start = seg.stream_frame_start as f64;
+            let end = start + seg.frames as f64;
+            if stream_frame >= start && stream_frame < end {
+                let diff = stream_frame - start;
+                return Some((
+                    diff.mul_add(seg.music_sec_per_frame, seg.music_start_sec),
+                    seg.music_sec_per_frame,
+                ));
+            }
+            let start_dist = (stream_frame - start).abs();
+            if start_dist < closest_dist {
+                closest_dist = start_dist;
+                closest = Some((seg, start, false));
+            }
+            let end_dist = (stream_frame - end).abs();
+            if end_dist < closest_dist {
+                closest_dist = end_dist;
+                closest = Some((seg, end, true));
+            }
+        }
+        // Only extrapolate if no segment contained the query, retaining the
+        // chosen endpoint and its arithmetic order.
+        closest.map(|(seg, anchor, at_end)| {
+            let music = if at_end {
+                seg.music_sec_per_frame
+                    .mul_add(seg.frames as f64, seg.music_start_sec)
+            } else {
+                seg.music_start_sec
+            };
+            (
+                (stream_frame - anchor).mul_add(seg.music_sec_per_frame, music),
+                seg.music_sec_per_frame,
+            )
+        })
+    }
+
+    /// Inverse of [`search`]: given a music position in seconds, return the
+    /// track-relative stream frame at which it plays. Prefers the segment that
+    /// contains `music_seconds`; otherwise extrapolates from the nearest segment.
+    #[must_use]
+    pub fn invert(&self, music_seconds: f64) -> Option<f64> {
+        if self.queue.is_empty() || !music_seconds.is_finite() {
+            return None;
+        }
+        let mut closest = None;
+        let mut closest_dist = f64::INFINITY;
+        for seg in &self.queue {
+            let sec_per_frame = seg.music_sec_per_frame;
+            // Insertion rejects non-finite slopes; zero slopes remain non-invertible.
+            if sec_per_frame == 0.0 {
+                continue;
+            }
+            let start_sec = seg.music_start_sec;
+            let end_sec = sec_per_frame.mul_add(seg.frames as f64, start_sec);
+            let (lo, hi) = if start_sec <= end_sec {
+                (start_sec, end_sec)
+            } else {
+                (end_sec, start_sec)
+            };
+            if music_seconds >= lo && music_seconds < hi {
+                return Some(
+                    seg.stream_frame_start as f64 + (music_seconds - start_sec) / sec_per_frame,
+                );
+            }
+            // Outside the segment, its nearest endpoint has the clamp's
+            // distance without clamping or validating the interval again.
+            let dist = (music_seconds - start_sec).abs().min((music_seconds - end_sec).abs());
+            if dist < closest_dist {
+                closest_dist = dist;
+                closest = Some(seg);
+            }
+        }
+        // Distance selection needs no division. Keep the first nearest segment
+        // on ties and convert only the selected result back to a stream frame.
+        closest.map(|seg| {
+            seg.stream_frame_start as f64
+                + (music_seconds - seg.music_start_sec) / seg.music_sec_per_frame
+        })
+    }
+}
