+#[cfg(test)]
+mod tests {
+    use super::{OutputTelemetryBackend, report_audio_render_callback};
+    use crate::RenderReport;
+    use std::cell::Cell;
+
+    #[test]
+    fn backend_diagnostic_ids_round_trip_on_every_target() {
+        for backend in [
+            OutputTelemetryBackend::AlsaShared,
+            OutputTelemetryBackend::AlsaExclusive,
+            OutputTelemetryBackend::PulseAudioShared,
+            OutputTelemetryBackend::JackShared,
+            OutputTelemetryBackend::PipeWireShared,
+            OutputTelemetryBackend::WasapiShared,
+            OutputTelemetryBackend::WasapiExclusive,
+            OutputTelemetryBackend::FreeBsdPcm,
+            OutputTelemetryBackend::CoreAudioShared,
+        ] {
+            assert_eq!(OutputTelemetryBackend::from_bits(backend as u8), backend);
+            assert_eq!(
+                OutputTelemetryBackend::from_backend_name(backend.as_str()),
+                backend
+            );
+        }
+    }
+
+    #[test]
+    fn clean_callbacks_do_not_read_the_host_clock() {
+        let clock_reads = Cell::new(0);
+        report_audio_render_callback(
+            RenderReport {
+                output_underrun: false,
+                callback_gap_ns: 0,
+            },
+            false,
+            || {
+                clock_reads.set(clock_reads.get() + 1);
+                123
+            },
+        );
+        assert_eq!(clock_reads.get(), 0);
+    }
+
+    #[test]
+    fn diagnostics_read_the_host_clock_at_most_once_per_callback() {
+        let clock_reads = Cell::new(0);
+        report_audio_render_callback(
+            RenderReport {
+                output_underrun: true,
+                callback_gap_ns: u64::MAX,
+            },
+            true,
+            || {
+                clock_reads.set(clock_reads.get() + 1);
+                456
+            },
+        );
+        assert_eq!(clock_reads.get(), 1);
+    }
+
+    #[test]
+    fn untraced_underruns_do_not_read_the_host_clock() {
+        let clock_reads = Cell::new(0);
+        report_audio_render_callback(
+            RenderReport {
+                output_underrun: true,
+                callback_gap_ns: 0,
+            },
+            false,
+            || {
+                clock_reads.set(clock_reads.get() + 1);
+                789
+            },
+        );
+        assert_eq!(clock_reads.get(), 0);
+    }
+}
