+    ActiveSfx, CallbackClockSource, MAX_ACTIVE_SFX, MixBus, MixControls, MusicMapSeg, QueuedSfx,
+    SfxPan, activate_music_track, bump_music_map_generation, f32_to_i16, i16_to_f32,
